-- 04/11/2026: IVA 10,5 por ciento para los bienes de capital de la Planilla Anexa al inciso e) del art. 28 de la
-- Ley de IVA (https://biblioteca.arca.gob.ar/pdfp/Planilla_Anexa_inciso_e.pdf, 1104 posiciones NCM).
-- La base solo tenía el 10,5 en el capítulo 90 (y 49): la calculadora cotizaba máquinas y equipos de los
-- capítulos 84/85 con IVA 21 y los clientes lo notaban. iva_nota guarda la excepción de la planilla
-- ("excepto sus partes", "excepto los de uso doméstico"...), que se muestra al lado del IVA.
-- La planilla trae posiciones viejas (8525.20.xx, 9009...) que ya no existen en la nomenclatura: esas no matchean.
alter table public.ncm_database add column if not exists iva_nota text;
create temp table planilla_e(ncm text primary key, nota text);
update public.ncm_database n set iva = 10.5, iva_nota = p.nota from planilla_e p where n.ncm_code = p.ncm;
select (select count(*) from planilla_e) en_planilla,
       (select count(distinct ncm_code) from public.ncm_database where ncm_code in (select ncm from planilla_e)) encontradas,
       (select count(*) from public.ncm_database where iva = 10.5) filas_105;
